/*
 * ---------------------------------------------------------------------------
 * Test harness: a mock requester and a mock responder that sit on either
 * side of the TutorialMemoryBridge.
 *
 *   MockRequester                                       MockResponder
 *  (RequestPort)  <---->  [ TutorialMemoryBridge ]  <---->  (ResponsePort)
 *   sends reqs            upstream       downstream         answers reqs
 *   receives resps                                          with responses
 * ---------------------------------------------------------------------------
 */

/**
 * A mock request port that drives read/write requests into the bridge's
 * upstream ResponsePort. It records responses for test verification.
 */
class MockRequesterPort : public RequestPort
{
  public:
    MockRequesterPort(const std::string &name)
        : RequestPort(name),
          responseCount(0),
          blockedPacket(nullptr)
    {}

    /** Build and send a read request for the given address. */
    void sendReadRequest(Addr addr, unsigned size)
    {
        auto req = std::make_shared<Request>(
            addr, size, Request::Flags(), Request::invldRequestorId);
        auto pkt = new Packet(req, MemCmd::ReadReq);
        pkt->allocate();
        sendPacket(pkt);
    }

    /** Build and send a write request for the given address. */
    void sendWriteRequest(Addr addr, unsigned size)
    {
        auto req = std::make_shared<Request>(
            addr, size, Request::Flags(), Request::invldRequestorId);
        auto pkt = new Packet(req, MemCmd::WriteReq);
        pkt->allocate();
        sendPacket(pkt);
    }

    unsigned responseCount;
    std::vector<std::string> responseLog;
    bool wasBlocked = false;

  protected:
    bool
    recvTimingResp(PacketPtr pkt) override
    {
        responseCount++;
        std::ostringstream entry;
        entry << "resp addr=0x" << std::hex << pkt->getAddr()
              << " cmd=" << pkt->cmd.toString();
        responseLog.push_back(entry.str());
        delete pkt;
        return true;
    }

    void
    recvReqRetry() override
    {
        PacketPtr pkt = blockedPacket;
        blockedPacket = nullptr;
        sendPacket(pkt);
    }

  private:
    void
    sendPacket(PacketPtr pkt)
    {
        if (!sendTimingReq(pkt)) {
            blockedPacket = pkt;
            wasBlocked = true;
        }
    }

    PacketPtr blockedPacket;
};

/**
 * A mock response port that acts as a trivial memory: it immediately
 * converts any incoming timing request into a response and sends it
 * back. This lets us test the bridge in isolation.
 */
class MockResponderPort : public ResponsePort
{
  public:
    MockResponderPort(const std::string &name, AddrRange range)
        : ResponsePort(name),
          requestCount(0),
          addrRange(range)
    {}

    unsigned requestCount;

  protected:
    AddrRangeList
    getAddrRanges() const override
    {
        return {addrRange};
    }

    Tick
    recvAtomic(PacketPtr pkt) override
    {
        pkt->makeAtomicResponse();
        return 1;
    }

    void
    recvFunctional(PacketPtr pkt) override
    {
        pkt->makeResponse();
    }

    bool
    recvTimingReq(PacketPtr pkt) override
    {
        requestCount++;
        pkt->makeResponse();
        sendTimingResp(pkt);
        return true;
    }

    void
    recvRespRetry() override
    {
    }

  private:
    AddrRange addrRange;
};


// ---------------------------------------------------------------------------
// Test fixture
// ---------------------------------------------------------------------------

class MemoryPortsTest : public ::testing::Test
{
  protected:
    EventQueue *queue = nullptr;
    EventQueue *savedQueue = nullptr;

    void
    SetUp() override
    {
        queue = getEventQueue(0);
        savedQueue = curEventQueue();
        curEventQueue(queue);

        while (!queue->empty()) {
            queue->serviceOne();
        }
        queue->setCurTick(0);
    }

    void
    TearDown() override
    {
        while (!queue->empty()) {
            queue->serviceOne();
        }
        queue->setCurTick(0);
        curEventQueue(savedQueue);
    }
};


