TEST_F(MemoryPortsTest, BackpressureBlocksSecondRequest)
{
    // Use a nonzero response latency so that the first request stays
    // in flight when the second one arrives.
    TutorialMemoryBridgeParams params;
    params.name = "test.bridge";
    params.eventq_index = 0;
    params.response_latency = 5;

    TutorialMemoryBridge bridge(params);

    MockRequesterPort requester("test.requester");
    MockResponderPort responder("test.responder",
                                AddrRange(0x0, 0x1000));

    Port &upPort = bridge.getPort("upstream");
    Port &downPort = bridge.getPort("downstream");

    requester.bind(upPort);
    downPort.bind(responder);

    bridge.init();

    // First request succeeds.
    requester.sendReadRequest(0x100, 4);
    EXPECT_EQ(bridge.requestsForwarded(), 1u);

    // Response is delayed, so bridge is still blocked.
    EXPECT_EQ(requester.responseCount, 0u);

    // Second request should be rejected (backpressure).
    requester.sendReadRequest(0x200, 4);
    EXPECT_TRUE(requester.wasBlocked);
    EXPECT_EQ(bridge.requestsForwarded(), 1u);

    // Drain all pending events. The first delayed response triggers a retry,
    // which resubmits the second request and schedules its delayed response.
    // runToCompletion() therefore delivers both responses.
    bridge.runToCompletion();

    // The retry should have allowed the second request through, and both
    // responses should have been delivered by the queue drain.
    EXPECT_EQ(bridge.requestsForwarded(), 2u);
    EXPECT_EQ(responder.requestCount, 2u);
    EXPECT_EQ(requester.responseCount, 2u);
    EXPECT_EQ(bridge.responsesDelivered(), 2u);
}

TEST_F(MemoryPortsTest, ResponseLatencyAddsDelay)
{
    TutorialMemoryBridgeParams params;
    params.name = "test.bridge";
    params.eventq_index = 0;
    params.response_latency = 10;

    TutorialMemoryBridge bridge(params);

    MockRequesterPort requester("test.requester");
    MockResponderPort responder("test.responder",
                                AddrRange(0x0, 0x1000));

    Port &upPort = bridge.getPort("upstream");
    Port &downPort = bridge.getPort("downstream");

    requester.bind(upPort);
    downPort.bind(responder);

    bridge.init();

    // Send at tick 0.
    requester.sendReadRequest(0x100, 4);

    // Not yet delivered.
    EXPECT_EQ(requester.responseCount, 0u);
    EXPECT_EQ(queue->getCurTick(), 0u);

    // Run to completion: response arrives at tick 10.
    bridge.runToCompletion();

    EXPECT_EQ(queue->getCurTick(), 10u);
    EXPECT_EQ(requester.responseCount, 1u);
    EXPECT_EQ(bridge.responsesDelivered(), 1u);
}

TEST_F(MemoryPortsTest, EventLogTracksRequestFlow)
{
    TutorialMemoryBridgeParams params;
    params.name = "test.bridge";
    params.eventq_index = 0;
    params.response_latency = 0;

    TutorialMemoryBridge bridge(params);

    MockRequesterPort requester("test.requester");
    MockResponderPort responder("test.responder",
                                AddrRange(0x0, 0x1000));

    Port &upPort = bridge.getPort("upstream");
    Port &downPort = bridge.getPort("downstream");

    requester.bind(upPort);
    downPort.bind(responder);

    bridge.init();

    requester.sendReadRequest(0x100, 4);

    const auto &log = bridge.eventLog();

    // Should contain: construct, init, forward-req, recv-resp,
    // deliver-resp.
    ASSERT_GE(log.size(), 5u);
    EXPECT_EQ(log[0], "tick=0 construct");
    EXPECT_EQ(log[1], "tick=0 init");
    EXPECT_NE(log[2].find("forward-req"), std::string::npos);
    EXPECT_NE(log[3].find("recv-resp"), std::string::npos);
    EXPECT_NE(log[4].find("deliver-resp"), std::string::npos);
}

